mapper.select:
select d.id, d.name, d.cat_id as productCategory_id, d.price, d.img as image, d.descr as description, d.status, d.create_time, d.update_time, d.create_uid as create_user, d.update_uid as update_user, c.name as productCategoryName from prod d left outer join cat c on d.cat_id = c.id
and d.name like concat('%',#{name},'%')
and d.cat_id = #{categoryId}
and d.status = #{status}
order by d.create_time desc

mapper.update:
update prod
name = #{name}, cat_id = #{categoryId}, price = #{price}, img = #{image}, descr = #{description}, status = #{status}, update_time = #{updateTime}, update_uid = #{updateUser},
where id = #{id}

